 if(action==='confirm-provided'){b.disabled=true;const e=newEntry('sermon');e.sourceMaterial=review.material;const d=entryDraft(e);await db.put('drafts',d);review=null;location.hash='#write/draft/'+encodeURIComponent(d.id);toast('Provided notes added to a new draft.');}
