 if(action==='pick-journal'||action==='pick-sermon'||action==='pick-pack-draft'){pickPurpose=action==='pick-sermon'?'sermon':action==='pick-pack-draft'?'pack-draft':'journal';picker.accept=pickPurpose==='journal'?'.json,.lwc,.zip,.txt,.md':pickPurpose==='sermon'?'.json,.txt,.md,.markdown':'.json';picker.value='';picker.click();}
 if(action==='cancel-import'){importReadVersion++;review=null;await route();}
 if(action==='confirm-pack-draft'){b.disabled=true;const restored={id:crypto.randomUUID(),value:clone(review.raw),updatedAt:new Date().toISOString()};await db.putPack(restored,undefined);packEditor=restored;packBase=clone(restored);review=null;location.hash='#church';toast('Church draft restored as a separate outline on this device. Validate it before publishing.');}
